(function(){'use strict';const C=CurationCore,esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),colors=['#166a91','#b14c1c','#6351a3','#317056','#a05c19','#9d355d'];
class CurationWorkspace{
 constructor(options){this.o=options;this.wave=new WaveformView();this.wave.updated=()=>this.o.updated?.();this.gridKey='';this.evidenceKey='';this.ccg=new Map();this.resizeTimer=null;window.addEventListener('resize',()=>{clearTimeout(this.resizeTimer);this.resizeTimer=setTimeout(()=>{this.gridKey='';this.evidenceKey='';this.render();},250);});}
 render(){const x=this.o.get();if(!x.input||!x.state)return;if(this.lastInput!==x.input){this.lastInput=x.input;this.gridKey='';this.evidenceKey='';}this.wave.load(x.input);this.grid(x);this.evidence(x);}
 grid(x){const {input,state,selected}=x,metrics=C.unitMetrics(input,state),sort=document.querySelector('#working-sort').value,query=document.querySelector('#working-search').value.trim(),key=input.data.source_sha256+'|'+state.labels.join(',')+'|'+sort+'|'+query;
  const units=C.units(input,state).sort((a,b)=>sort==='quality'?(metrics.get(a.id).rate??Infinity)-(metrics.get(b.id).rate??Infinity)||b.n-a.n:b.n-a.n||(metrics.get(a.id).rate??Infinity)-(metrics.get(b.id).rate??Infinity)||a.id-b.id).filter(u=>!query||String(u.id).includes(query));
  if(key!==this.gridKey){this.gridKey=key;const el=document.querySelector('#working-tasks');el.innerHTML=units.map(u=>`<button class="cluster-tile" data-working-task="cluster:${u.id}" data-tile-id="${u.id}"><div class="tile-heading"><strong>Cluster ${u.id}</strong><span class="tile-role"></span></div><canvas aria-label="Cluster ${u.id} member waveforms"></canvas><small class="tile-wave-status"></small><div class="tile-stats"><span>${u.n.toLocaleString()} spikes</span><span title="All N−1 intervals; 2 ms is a descriptive threshold, not an automatic rule">ISI &lt;2 ms: ${metrics.get(u.id).rate==null?'—':(100*metrics.get(u.id).rate).toFixed(2)+'%'}</span></div><small class="tile-review-status"></small></button>`).join('')||'<p class="input-help">No matching clusters.</p>';
   for(const tile of el.querySelectorAll('[data-tile-id]')){const id=Number(tile.dataset.tileId);tile.onclick=e=>{const selected=this.o.get().selected;if(e.shiftKey&&selected&&selected.source!==id)this.o.pick(C.task(selected.source,id));else this.o.pick(C.task(id));};const canvas=tile.querySelector('canvas');this.wave.draw(canvas,tile.querySelector('.tile-wave-status'),state.labels,[{id,color:'#607f8b'}],true);}
  }
  const suggestion=selected?C.suggestion(input,x.hash,selected,x.agent):null;for(const tile of document.querySelectorAll('[data-tile-id]')){const id=Number(tile.dataset.tileId),source=selected?.source===id,target=selected?.target===id;tile.classList.toggle('selected-source',source);tile.classList.toggle('selected-target',target);tile.classList.toggle('agent-object',!!suggestion&&(suggestion.source===id||suggestion.target===id));tile.setAttribute('aria-pressed',String(source||target));tile.querySelector('.tile-role').textContent=(source?'Selected':target?'Compare':'')+(suggestion&&(suggestion.source===id||suggestion.target===id)?' · AI':'');const color=source?colors[0]:target?colors[1]:'#607f8b',canvas=tile.querySelector('canvas');if(canvas.dataset.color!==color){canvas.dataset.color=color;this.wave.draw(canvas,tile.querySelector('.tile-wave-status'),state.labels,[{id,color}],true);}tile.querySelector('.tile-review-status').textContent=state.kept[id]===C.signature(state,id)?'✓ Kept':state.deferred['cluster:'+id]?'Deferred':'Needs review';}
 }
 plot(groups,state,caption,mini=false,axisGroups=groups,role='overlay'){const id='wave-'+Math.random().toString(36).slice(2);this.pending.push({id,groups,state,mini,axisGroups,role});return `<section class="working-plot full-wave-plot" data-wave-role="${role}"><div class="plot-heading"><h3>${esc(caption)}</h3><div class="plot-tools"><button class="button small" data-wave-expand="${id}">Expand</button><label>Zoom<input type="range" min="1" max="80" step=".25" value="1" data-wave-zoom="${id}" aria-label="Waveform amplitude zoom"></label><label>Opacity<input type="range" min=".02" max="1" step=".02" value=".18" data-wave-opacity="${id}" aria-label="Individual waveform opacity"></label></div></div><div class="plot-key">${groups.map(g=>`<span style="color:${g.color}">Cluster ${g.id}${g.n==null?'':' · '+g.n.toLocaleString()+' spikes'}</span>`).join(' · ')}</div><canvas id="${id}" aria-label="Individual member waveforms on common axes"></canvas><p class="wave-status input-help"></p></section>`;}

 memberBrowser(group,state,axisGroups,onReady){const id='members-'+Math.random().toString(36).slice(2);this.membersPending.push({id,group,state,axisGroups,onReady});return `<section class="individual-member-section" id="${id}" data-member-cluster="${group.id}" data-loaded="false"><h3 style="color:${group.color}">Cluster ${group.id} · ${group.n.toLocaleString()} members</h3><p class="member-page-status" role="status">Loading individual waveforms…</p><div class="member-page-controls"><label>Order<select data-member-order><option value="row">Original spike row</option><option value="amplitude">Peak-to-peak amplitude ↓</option></select></label><label>Per page<select data-member-size><option>12</option><option selected>24</option><option>48</option></select></label></div><p class="member-shared-axes input-help"></p><div class="member-items"></div><div class="member-page-controls member-pagination"><button class="button small" data-member-first>First</button><button class="button small" data-member-prev>Previous</button><label>Page<input data-member-page type="number" min="1" value="1" aria-label="Waveform page for cluster ${group.id}"></label><button class="button small" data-member-go>Go</button><span class="member-pages"></span><button class="button small" data-member-next>Next</button><button class="button small" data-member-last>Last</button></div></section>`;}
 memberSVG(item,low,high,color){const points=item.waveform.map((v,i)=>(12+i/(item.waveform.length-1)*196).toFixed(3)+','+(16+(high-v)/(high-low)*76).toFixed(3)).join(' '),zero=16+high/(high-low)*76;return `<svg viewBox="0 0 220 110" role="img" aria-label="Individual waveform for spike row ${item.row+1}"><path d="M12 16H208M12 54H208M12 92H208" stroke="#e1e9ef" fill="none"/><path d="M12 ${zero}H208" stroke="#adbdc9" stroke-dasharray="3 3"/><polyline points="${points}" fill="none" stroke="${color}" stroke-width="1.35" stroke-linejoin="round"/><text x="12" y="106">0 ms</text><text x="208" y="106" text-anchor="end">${((this.lastInput.data.n_samples-1)/this.lastInput.data.sampling_rate_hz*1000).toFixed(3)} ms</text></svg>`;}
 mountMembers(config){const section=document.getElementById(config.id),get=s=>section.querySelector(s);let page=1,pages=1,size=24,order='row',generation=0;
  const load=()=>{const request=++generation;section.dataset.loaded='false';get('.member-page-status').textContent='Loading individual waveforms…';for(const b of section.querySelectorAll('button,select,input'))b.disabled=true;this.wave.members(config.state.labels,config.axisGroups,config.group.id,page,size,order,m=>{if(!section.isConnected||request!==generation)return;for(const b of section.querySelectorAll('button,select,input'))b.disabled=false;if(m.error){get('.member-page-status').textContent='Individual waveforms unavailable: '+m.error;return;}if(m.full&&m.total!==config.group.n){get('.member-page-status').textContent='Member count mismatch. Reload the complete private package.';return;}page=m.page;pages=m.pages;section.dataset.loaded='true';section.dataset.total=m.total;section.dataset.full=m.full;section.dataset.yMin=m.low;section.dataset.yMax=m.high;section.dataset.order=m.order;get('[data-member-page]').value=page;get('[data-member-page]').max=pages;get('.member-pages').textContent='/ '+pages.toLocaleString();get('[data-member-first]').disabled=get('[data-member-prev]').disabled=page<=1;get('[data-member-last]').disabled=get('[data-member-next]').disabled=page>=pages;get('.member-page-status').textContent=m.full?`All ${m.total.toLocaleString()} members are available · showing ${m.total?m.start+1:0}–${Math.min(m.start+m.items.length,m.total)} · one spike per tile`:`Legacy sampled input: only ${m.total.toLocaleString()} stored waveforms are available, out of ${config.group.n.toLocaleString()} members. Load the full package on Runpod.`;get('.member-shared-axes').textContent=`Shared amplitude limits: ${m.low.toPrecision(4)} to ${m.high.toPrecision(4)} source units. Click a waveform to expand it.`;
   get('.member-items').innerHTML=m.items.map((item,i)=>`<button class="member-spike" data-spike-row="${item.row}" data-wave-samples="${esc(JSON.stringify(item.waveform))}" aria-label="Expand spike row ${item.row+1} in cluster ${config.group.id}"><strong>Spike row ${item.row+1}</strong><small>${item.time.toFixed(6)} s · P–P ${item.amplitude.toPrecision(4)}</small>${this.memberSVG(item,m.low,m.high,config.group.color)}</button>`).join('');for(const [i,button] of [...get('.member-items').children].entries())button.onclick=()=>{const item=m.items[i],dialog=document.querySelector('#working-plot-dialog'),host=document.querySelector('#working-expanded-plot');host.innerHTML=`<section class="expanded-member working-plot"><h3>Cluster ${config.group.id} · spike row ${item.row+1}</h3><p>${item.time.toFixed(6)} s · peak-to-peak ${item.amplitude.toPrecision(6)} source units</p>${this.memberSVG(item,m.low,m.high,config.group.color)}<p>One original spike waveform · ${item.waveform.length} original samples. Shared amplitude limits ${m.low.toPrecision(4)} to ${m.high.toPrecision(4)}.</p></section>`;dialog.showModal();};config.onReady?.();});};
  get('[data-member-order]').onchange=e=>{order=e.target.value;page=1;load();};get('[data-member-size]').onchange=e=>{size=Number(e.target.value);page=1;load();};get('[data-member-first]').onclick=()=>{page=1;load();};get('[data-member-prev]').onclick=()=>{page--;load();};get('[data-member-next]').onclick=()=>{page++;load();};get('[data-member-last]').onclick=()=>{page=pages;load();};const go=()=>{page=Math.max(1,Math.min(pages,Number(get('[data-member-page]').value)||1));load();};get('[data-member-go]').onclick=go;get('[data-member-page]').onkeydown=e=>{if(e.key==='Enter')go();};load();
 }
 histogram(isi,title){const max=Math.max(...isi.counts,1);return `<section class="working-plot"><h3>${title}</h3><svg viewBox="0 0 610 220" role="img" aria-label="${title}">${isi.counts.map((n,i)=>`<rect x="${45+i*5.4}" y="${180-150*n/max}" width="5.4" height="${150*n/max}" fill="#367a99"/>`).join('')}<path d="M${45+2/50*540} 24v156" stroke="#a94f19" stroke-dasharray="5 4"/><text x="45" y="206">0 ms</text><text x="585" y="206" text-anchor="end">50 ms</text><text x="45" y="16">${isi.violation_count} / ${isi.denominator} intervals &lt; 2 ms (${isi.violation_rate==null?'—':(100*isi.violation_rate).toFixed(3)+'%'})</text></svg><p class="input-help">All member intervals; 0–50 ms displayed. No quality cutoff is automatically applied.</p></section>`;}
 histograms(root,expanded=false){for(const svg of root.querySelectorAll('.working-plot>svg')){const section=svg.parentElement,title=section.querySelector('h3'),heading=document.createElement('div'),tools=document.createElement('div'),viewport=document.createElement('div');heading.className='plot-heading';tools.className='plot-tools';tools.innerHTML='<button class="button small">Expand</button><label>Zoom<input type="range" min="1" max="6" step=".25" value="1" aria-label="Histogram zoom"></label>';viewport.className='histogram-viewport';section.insertBefore(heading,title);heading.append(title,tools);svg.replaceWith(viewport);viewport.append(svg);tools.querySelector('input').oninput=e=>{svg.style.width=(Number(e.target.value)*100)+'%';};const button=tools.querySelector('button');button.hidden=expanded;button.onclick=()=>{const dialog=document.querySelector('#working-plot-dialog'),host=document.querySelector('#working-expanded-plot'),copy=document.createElement('section');copy.className='working-plot';const graph=svg.cloneNode(true);graph.style.width='100%';copy.append(title.cloneNode(true),graph);host.replaceChildren(copy);dialog.showModal();this.histograms(host,true);};}}
 evidence(x){const {input,state,selected,preview,tab}=x;if(!selected){document.querySelector('#working-evidence').innerHTML='<div class="empty-state">No active clusters. Export the result or undo the last operation.</div>';return;}const usePreview=preview&&!document.querySelector('#preview-current').checked,viewState=usePreview?preview.state:state,key=[input.data.source_sha256,viewState.labels.join(','),viewState.tree[0].length,selected.source,selected.target,tab,!!usePreview].join('|');if(this.evidenceKey===key)return;this.evidenceKey=key;this.pending=[];this.membersPending=[];
  const all=C.units(input,viewState),ids=usePreview?(preview.action==='MERGE'?[selected.target]:[selected.source,C.splitPlan(input,state,selected.source).breakaway]):[selected.source,selected.target].filter(v=>v!=null),units=ids.map(id=>all.find(u=>u.id===id)).filter(Boolean),groups=units.map((u,i)=>({id:u.id,n:u.n,color:colors[i]}));let html='';
  if(tab==='quality'){const q=units.map(u=>C.quality(input,viewState,u.id));html='<div class="activity-table-wrap"><table class="working-quality"><thead><tr><th>Metric</th>'+q.map(u=>`<th>Cluster ${u.id}</th>`).join('')+'</tr></thead><tbody>'+[['Spikes',u=>u.n.toLocaleString()],['ISI <2 ms',u=>u.isi.violation_rate==null?'—':(u.isi.violation_rate*100).toFixed(3)+'%'],['Amplitude mean ± SD',u=>u.mean_amplitude.toFixed(3)+' ± '+u.amplitude_sd.toFixed(3)],['Amplitude CV',u=>u.amplitude_cv?.toFixed(3)??'—'],['Late vs early amplitude',u=>u.drift_percent==null?'—':u.drift_percent.toFixed(2)+'%']].map(([n,fn])=>'<tr><th>'+n+'</th>'+q.map(u=>'<td>'+fn(u)+'</td>').join('')+'</tr>').join('')+'</tbody></table></div><p class="input-help">All member spikes. ISI uses N−1 intervals; drift compares first/last 20% of spikes by time. These are descriptive measurements, not a sorter-provided quality score.</p>';}
  else if(tab==='isi'){html=units.map(u=>this.histogram(C.quality(input,viewState,u.id).isi,'Cluster '+u.id+' · ISI')).join('');if(units.length===2)html+=this.histogram(C.pairISI(input,viewState,units[0].id,units[1].id),'If merged · pooled ISI');}
  else if(tab==='ccg'){html='<div id="working-ccg" class="working-plot"><h3>Calculating all-spike correlogram…</h3></div>';setTimeout(()=>{if(this.evidenceKey!==key)return;const a=units[0].id,b=units[1]?.id??a,cacheKey=viewState.labels.join(',')+'|'+a+'|'+b;let cc=this.ccg.get(cacheKey);if(!cc){cc=C.correlogram(input,viewState,a,b);this.ccg.set(cacheKey,cc);while(this.ccg.size>30)this.ccg.delete(this.ccg.keys().next().value);}const el=document.querySelector('#working-ccg');if(!el||this.evidenceKey!==key)return;const max=Math.max(...cc.counts,1);el.innerHTML=`<h3>${a===b?'Auto':'Cross'}-correlogram · Cluster ${a}${a===b?'':' vs. '+b}</h3><svg viewBox="0 0 610 220" role="img" aria-label="All-spike correlogram">${cc.counts.map((n,i)=>`<rect x="${45+i*5.4}" y="${180-150*n/max}" width="5.4" height="${150*n/max}" fill="#367a99"/>`).join('')}<text x="45" y="206">−50 ms</text><text x="315" y="206" text-anchor="middle">0</text><text x="585" y="206" text-anchor="end">+50 ms</text><text x="45" y="16">Raw pair counts · max ${max.toLocaleString()}</text></svg><p class="input-help">All spike pairs; lag = target − source, 1 ms bins over [−50,50) ms. ${a===b?'Self-pairs excluded.':'No normalization.'} This is a timing histogram, not waveform correlation or proof of a shared neuron.</p>`;this.histograms(el.parentElement);},30);}
  else{
   const mergePreview=usePreview&&preview.action==='MERGE',waveState=mergePreview?state:viewState,waveUnits=mergePreview?[selected.source,selected.target].map(id=>C.units(input,state).find(u=>u.id===id)):units,waveGroups=waveUnits.map((u,i)=>({id:u.id,n:u.n,color:colors[i]}));
   html=`<p class="member-waveform-note ${input.data.arrays.waveforms?'':'legacy-waveform-note'}">${input.data.arrays.waveforms?'Each tile below is one original spike waveform. Pages cover every member, without random sampling or averaging.':'Stored samples only: this legacy package does not contain every waveform. Upgrade the private package on Runpod to inspect all members.'}${mergePreview?' Original cluster colors are retained below; confirmation assigns their combined members to Cluster '+selected.target+'.':''}</p>`;
   const readyMembers=new Set(),ready=id=>{readyMembers.add(id);if(usePreview&&this.o.get().preview===preview&&readyMembers.size>=waveGroups.length){preview.ready=true;this.o.updated?.();}};html+='<div class="individual-members-layout '+(waveGroups.length===2?'two-clusters':'')+'">'+waveGroups.map(g=>this.memberBrowser(g,waveState,waveGroups,()=>ready(g.id))).join('')+'</div>';html+='<details class="all-waveforms-overlay"><summary>Overlay all waveforms · optional combined view</summary><p class="input-help">This draws every member on shared axes. Dense populations overlap; inspect individual spikes in the browser above.</p>';html+=this.plot(waveGroups,waveState,usePreview?(mergePreview?'Merge preview · compare both original populations':'Split preview · both child populations'):waveGroups.length===2?'Compare · both complete populations':'Selected member waveforms');
   if(waveGroups.length===2)html+='<div class="member-waveform-pair">'+waveGroups.map((g,i)=>this.plot([g],waveState,(usePreview&&!mergePreview?'Split child':'Cluster')+' '+g.id+' · individual waveforms',false,waveGroups,i?'target':'source')).join('')+'</div>';
   if(waveGroups.length===2)html+='<p class="input-help">The overlay and both individual panels use the same time and amplitude limits. Zoom changes the viewport only; it does not remove spikes.</p>';
   html+='</details>';if(usePreview)html+=units.map(u=>this.histogram(C.quality(input,viewState,u.id).isi,'Projected Cluster '+u.id+' · ISI')).join('');
  }

  document.querySelector('#working-evidence').innerHTML=html;this.histograms(document.querySelector('#working-evidence'));for(const config of this.membersPending)this.mountMembers(config);const overlay=document.querySelector('.all-waveforms-overlay');if(overlay){overlay.ontoggle=()=>{for(const job of this.pending){const canvas=document.getElementById(job.id),status=canvas.parentElement.querySelector('.wave-status');if(!overlay.open){this.wave.cancel(canvas);continue;}const draw=()=>this.wave.draw(canvas,status,job.state.labels,job.groups,false,Number(document.querySelector(`[data-wave-zoom="${job.id}"]`).value),null,job.axisGroups,Number(document.querySelector(`[data-wave-opacity="${job.id}"]`).value));draw();document.querySelector(`[data-wave-zoom="${job.id}"]`).oninput=draw;document.querySelector(`[data-wave-opacity="${job.id}"]`).oninput=draw;document.querySelector(`[data-wave-expand="${job.id}"]`).onclick=()=>{const dialog=document.querySelector('#working-plot-dialog'),host=document.querySelector('#working-expanded-plot');host.innerHTML='<canvas style="width:100%;height:400px"></canvas><p class="wave-status"></p>';dialog.showModal();this.wave.draw(host.querySelector('canvas'),host.querySelector('p'),job.state.labels,job.groups,false,1,null,job.axisGroups,Number(document.querySelector(`[data-wave-opacity="${job.id}"]`).value));};}};}

 }
}
window.CurationWorkspace=CurationWorkspace;
})();
